import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { Icon, Table, message } from 'antd'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import UploadRenewalModal from './components/UploadRenewalModal'
import { styles } from './index.style'
import { formatTimestamp } from './utils'
import authGet from '../../../../request/methods/authGet'
import { formatDate, getUser } from '../../../../helpers/utility'
import authPostFormData from '../../../../request/methods/authPostFormData'

const RENEWAL_DECISION_LIST_URL = `${process.env.REACT_APP_API_ENDPOINT}/api/renewal-decision/`
const RENEWAL_DECISION_SUMMARY_URL = `${process.env.REACT_APP_API_ENDPOINT}/api/renewal-decision/summary/`
const RENEWAL_DECISION_UPLOAD_URL = `${process.env.REACT_APP_API_ENDPOINT}/api/renewal-decision/upload/`
const DEFAULT_LIMIT = 10

const PageHeader = ({ onUploadClick }) => (
  <div
    style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      width: '100%'
    }}
  >
    <p style={{ fontSize: 24, fontWeight: 700, color: '#424951', margin: 0 }}>
      Renewal Policy
    </p>
    <button
      type='button'
      onClick={onUploadClick}
      style={{
        border: 0,
        borderRadius: 6,
        background: '#1a74d8',
        color: '#fff',
        padding: '12px 18px',
        fontSize: 16,
        fontWeight: 600,
        cursor: 'pointer',
        boxShadow: '0 4px 10px rgba(26, 116, 216, 0.3)',
        display: 'flex',
        alignItems: 'center',
        gap: 8
      }}
    >
      <Icon type='cloud-upload' />
      Upload New Data Sheet
    </button>
  </div>
)

const SummaryCard = ({ activeSubmissions, expiredSubmissions, loading }) => (
  <div style={{ ...styles.card, width: '100%', padding: 24 }}>
    <p style={styles.sectionLabel}>SUMMARY</p>
    <div style={{ display: 'flex', gap: 10 }}>
      <div
        style={{ flex: 1, background: '#e3f4e8', borderRadius: 4, padding: 16 }}
      >
        <p style={styles.statLabel}>ACTIVE SUBMISSIONS</p>
        <p style={styles.statValue}>
          {loading ? '...' : Number(activeSubmissions || 0).toLocaleString()}
        </p>
      </div>
      <div
        style={{ flex: 1, background: '#f2f5f9', borderRadius: 4, padding: 16 }}
      >
        <p style={styles.statLabel}>EXPIRED SUBMISSIONS</p>
        <p style={styles.statValue}>
          {loading ? '...' : Number(expiredSubmissions || 0).toLocaleString()}
        </p>
      </div>
    </div>
  </div>
)

const RenewalPolicy = () => {
  const [modalVisible, setModalVisible] = useState(false)
  const [uploadRows, setUploadRows] = useState([])
  const [listPagination, setListPagination] = useState({
    offset: 0,
    limit: DEFAULT_LIMIT,
    total: 0
  })
  const [summary, setSummary] = useState({
    activeSubmissions: 0,
    expiredSubmissions: 0
  })
  const [loadingList, setLoadingList] = useState(false)
  const [loadingSummary, setLoadingSummary] = useState(false)

  const fetchUploadList = useCallback(async (paginationOverride = {}) => {
    const nextOffset =
      paginationOverride.offset !== undefined
        ? paginationOverride.offset
        : 0
    const nextLimit =
      paginationOverride.limit !== undefined
        ? paginationOverride.limit
        : DEFAULT_LIMIT

    setLoadingList(true)
    try {
      const response = await authGet({
        url: RENEWAL_DECISION_LIST_URL,
        query: {
          offset: nextOffset,
          limit: nextLimit
        }
      })
      const details = response?.data?.data?.details || []
      const metadata = response?.data?.data?.metadata || {}
      const total = metadata.count
      const mappedRows = details.map((item) => ({
        id: item.id,
        timestamp: formatTimestamp(item.created_at),
        fileName: item.file_name,
        fileUrl: item.file_url,
        processedBy: item.uploaded_by || '-',
        product: item?.product?.name || item?.product?.code || '-',
        provider: item?.provider?.name || item?.provider?.code || '-',
        renewal_month: item.renewal_month || '-'
      }))
      setUploadRows(mappedRows)
      setListPagination((prev) => ({
        ...prev,
        offset: nextOffset,
        limit: nextLimit,
        total
      }))
    } catch (error) {
      message.error(
        error?.data?.message || error?.message || 'Failed to load renewal list.'
      )
    } finally {
      setLoadingList(false)
    }
  }, [])

  const fetchSummary = useCallback(async () => {
    setLoadingSummary(true)
    try {
      const response = await authGet({ url: RENEWAL_DECISION_SUMMARY_URL })
      const details = response?.data?.data?.details || {}
      setSummary({
        activeSubmissions: details.active,
        expiredSubmissions: details.expired
      })
    } catch (error) {
      message.error(
        error?.data?.message ||
          error?.message ||
          'Failed to load renewal summary.'
      )
    } finally {
      setLoadingSummary(false)
    }
  }, [])

  useEffect(() => {
    fetchUploadList({ offset: 0, limit: DEFAULT_LIMIT })
    fetchSummary()
  }, [fetchSummary, fetchUploadList])

  const uploadColumns = useMemo(
    () => [
      {
        title: 'TIMESTAMP',
        dataIndex: 'timestamp',
        key: 'timestamp',
        render: text => formatDate(text, 'MMM DD, YYYY HH:mm A')
      },
      {
        title: 'FILE NAME',
        dataIndex: 'fileName',
        key: 'fileName',
        render: (fileName, row) => (
          <span style={{ fontWeight: 600 }}>
            <Icon type='file-text' style={{ color: '#2f6fb4', marginRight: 8 }} />
            {row.fileUrl
              ? (
                <a
                  href={row.fileUrl}
                  target='_blank'
                  rel='noopener noreferrer'
                  style={{ color: '#2f6fb4' }}
                >
                  {fileName}
                </a>
                )
              : (
                  fileName
                )}
          </span>
        )
      },
      {
        title: 'RENEWAL MONTH',
        dataIndex: 'renewal_month',
        key: 'renewal_month',
        render: (text) => <span style={{ color: '#4e5b66' }}>{formatDate(text, 'MMM-YYYY')}</span>
      },
      {
        title: 'PROVIDER',
        dataIndex: 'provider',
        key: 'provider',
        render: (text) => <span style={{ color: '#4e5b66' }}>{text}</span>
      },
      {
        title: 'PROCESSED BY',
        dataIndex: 'processedBy',
        key: 'processedBy',
        render: (text) => <span style={{ color: '#4e5b66' }}>{text}</span>
      }
    ],
    []
  )

  const handleUploadComplete = useCallback(
    async ({ file, productCode, providerCode, renewalMonth }) => {
      const currentUser = getUser()
      const uploadedBy =
        currentUser?.email || currentUser?.username || 'unknown@pasarpolis.com'

      const fd = new FormData()

      fd.append('product_code', productCode)
      fd.append('provider_code', providerCode)
      fd.append('renewal_month', renewalMonth)
      fd.append('uploaded_by', uploadedBy)
      fd.append('file', file)

      await authPostFormData({ url: RENEWAL_DECISION_UPLOAD_URL, body: fd })

      await Promise.all([
        fetchUploadList({ offset: 0, limit: listPagination.limit }),
        fetchSummary()
      ])
    },
    [fetchSummary, fetchUploadList, listPagination.limit]
  )

  const handleTableChange = useCallback(
    (pagination) => {
      const nextLimit = pagination?.pageSize || listPagination.limit
      const nextPage = pagination?.current || 1
      const nextOffset = (nextPage - 1) * nextLimit
      fetchUploadList({ offset: nextOffset, limit: nextLimit })
    },
    [fetchUploadList, listPagination.limit]
  )

  return (
    <LayoutContentWrapper
      style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}
    >
      <PageHeader onUploadClick={() => setModalVisible(true)} />

      <SummaryCard
        activeSubmissions={summary.activeSubmissions}
        expiredSubmissions={summary.expiredSubmissions}
        loading={loadingSummary}
      />

      <div
        style={{
          ...styles.card,
          padding: '22px 24px 12px',
          display: 'flex',
          flexDirection: 'column'
        }}
      >
        <h4 style={{ marginBottom: 14, fontSize: 18, fontWeight: 700 }}>
          Recent Uploads
        </h4>
        <Table
          columns={uploadColumns}
          dataSource={uploadRows}
          rowKey={(row) => String(row.id || row.fileName)}
          locale={{ emptyText: 'No uploads yet' }}
          loading={loadingList}
          pagination={{
            current: Math.floor(listPagination.offset / listPagination.limit) + 1,
            pageSize: listPagination.limit,
            total: listPagination.total,
            showSizeChanger: true
          }}
          onChange={handleTableChange}
        />
      </div>

      <UploadRenewalModal
        visible={modalVisible}
        onClose={() => setModalVisible(false)}
        onUploadComplete={handleUploadComplete}
      />
    </LayoutContentWrapper>
  )
}

export default RenewalPolicy
