import React, { useEffect, useMemo, useRef, useState } from 'react'
import moment from 'moment'
import { DatePicker, Icon, Modal, Select, Spin, message } from 'antd'
import { connect } from 'react-redux'
import productConfigAction from '../../../../redux/productConfig/actions'
import { ACCEPTED_EXTENSIONS, isValidFile } from '../utils'

const { Option } = Select
const { MonthPicker } = DatePicker
const mapToOption = (item) => {
  const value = item?.code
  const label = item?.name
  return { value: String(value), label: String(label) }
}

const UploadRenewalModal = ({
  visible,
  onClose,
  onUploadComplete,
  providerConfig,
  dispatchGetProviderConfig
}) => {
  const fileInputRef = useRef(null)
  const [dragOver, setDragOver] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [selectedFile, setSelectedFile] = useState(null)
  const [selectedProvider, setSelectedProvider] = useState(undefined)
  const [renewalMonth, setRenewalMonth] = useState(null)
  const providerOptions = useMemo(
    () => providerConfig?.data?.details?.map((item) => mapToOption(item)) || [],
    [providerConfig]
  )

  const canSubmit = useMemo(
    () =>
      Boolean(
        selectedFile &&
        selectedProvider &&
        renewalMonth &&
        !uploading
      ),
    [renewalMonth, selectedFile, selectedProvider, uploading]
  )

  const resetForm = () => {
    setSelectedFile(null)
    setSelectedProvider(undefined)
    setRenewalMonth(null)
    setUploading(false)
    setDragOver(false)
  }

  const handleClose = () => {
    resetForm()
    onClose()
  }

  useEffect(() => {
    if (visible) {
      dispatchGetProviderConfig({ query: {} })
    }
  }, [dispatchGetProviderConfig, visible])

  const handleFile = (file) => {
    if (!isValidFile(file)) {
      message.error(
        `Only ${ACCEPTED_EXTENSIONS.join(' ')} files are accepted.`
      )
      return
    }
    setSelectedFile(file)
  }

  const handleDrop = (e) => {
    e.preventDefault()
    setDragOver(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }

  const handleInputChange = (e) => {
    const file = e.target.files[0]
    if (file) handleFile(file)
    e.target.value = ''
  }

  const handleSubmit = async () => {
    if (!canSubmit) return
    setUploading(true)

    try {
      await onUploadComplete({
        file: selectedFile,
        providerCode: selectedProvider,
        renewalMonth: renewalMonth.format('YYYY-MM-01')
      })
      message.success(`"${selectedFile.name}" uploaded successfully.`)
      handleClose()
    } catch (error) {
      message.error(
        error?.data?.message ||
          error?.message ||
          error?.statusText ||
          'Failed to submit renewal upload.'
      )
      setUploading(false)
    }
  }

  return (
    <Modal
      title='Upload New Data Sheet'
      visible={visible}
      onCancel={handleClose}
      footer={null}
      destroyOnClose
    >
      <input
        ref={fileInputRef}
        type='file'
        accept={ACCEPTED_EXTENSIONS.join(',')}
        style={{ display: 'none' }}
        onChange={handleInputChange}
      />

      <div style={{ display: 'grid', gap: 12, marginBottom: 16 }}>
        <div>
          <p style={{ marginBottom: 6, fontWeight: 600 }}>Provider</p>
          <Select
            showSearch
            style={{ width: '100%' }}
            placeholder='Select provider'
            optionFilterProp='children'
            value={selectedProvider}
            onChange={setSelectedProvider}
            loading={false}
            disabled={uploading}
          >
            {providerOptions.map((item) => (
              <Option key={item.value} value={item.value}>
                {item.label}
              </Option>
            ))}
          </Select>
        </div>

        <div>
          <p style={{ marginBottom: 6, fontWeight: 600 }}>Renewal Month</p>
          <MonthPicker
            style={{ width: '100%' }}
            placeholder='Select renewal month'
            value={renewalMonth}
            onChange={setRenewalMonth}
            format='MMM YYYY'
            disabled={uploading}
            disabledDate={(current) => current && current.isBefore(moment().startOf('month'))}
          />
        </div>
      </div>

      <div
        onClick={() => !uploading && fileInputRef.current.click()}
        onDragOver={(e) => {
          e.preventDefault()
          setDragOver(true)
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        style={{
          border: `2px dashed ${dragOver ? '#1a74d8' : '#d0d7de'}`,
          borderRadius: 8,
          padding: '32px 24px',
          textAlign: 'center',
          cursor: uploading ? 'not-allowed' : 'pointer',
          background: dragOver ? '#f0f7ff' : '#fafbfc',
          transition: 'all 0.2s ease',
          marginBottom: 16
        }}
      >
        <Icon
          type='inbox'
          style={{ fontSize: 40, color: '#1a74d8', marginBottom: 12 }}
        />
        <p style={{ margin: 0, fontWeight: 600, color: '#2b2f33' }}>
          {selectedFile
            ? selectedFile.name
            : 'Click or drag a file here to upload'}
        </p>
        <p style={{ margin: '4px 0 0', fontSize: 12, color: '#8a96a3' }}>
          Supported formats: {ACCEPTED_EXTENSIONS.join(', ')}
        </p>
      </div>

      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
        <button
          type='button'
          onClick={handleClose}
          disabled={uploading}
          style={{
            padding: '8px 16px',
            borderRadius: 6,
            border: '1px solid #d0d7de',
            background: '#fff',
            cursor: uploading ? 'not-allowed' : 'pointer',
            fontWeight: 600
          }}
        >
          Cancel
        </button>
        <button
          type='button'
          onClick={handleSubmit}
          disabled={!canSubmit}
          style={{
            padding: '8px 16px',
            borderRadius: 6,
            border: 0,
            background: !canSubmit ? '#a0b8d8' : '#1a74d8',
            color: '#fff',
            cursor: !canSubmit ? 'not-allowed' : 'pointer',
            fontWeight: 600,
            display: 'flex',
            alignItems: 'center',
            gap: 8
          }}
        >
          {uploading && <Spin size='small' style={{ lineHeight: 1 }} />}
          {uploading ? 'Submitting...' : 'Submit'}
        </button>
      </div>
    </Modal>
  )
}

const mapStateToProps = (state) => ({
  providerConfig: state.ProductConfigurable?.getAllProviders
})

const mapDispatchToProps = (dispatch) => ({
  dispatchGetProviderConfig: (payload) =>
    dispatch(productConfigAction.getAllProductProviders(payload))
})

export default connect(mapStateToProps, mapDispatchToProps)(UploadRenewalModal)
